import heapq
class Solution:
    def maxEarnings(self, meetings: list[list[int]]) -> int:
        meetings.sort(); heap = []; best = None; answer = 0
        for start, end, revenue in meetings:
            while heap and heap[0][0] <= start:
                finish, value = heapq.heappop(heap); best = value - finish if best is None else max(best, value - finish)
            value = revenue + (max(0, best + start) if best is not None else 0)
            answer = max(answer, value); heapq.heappush(heap, (end, value))
        return answer
